try {
  const items = $input.all();
  // دریافت داده از بدنه وب‌هوک یا ریشه
  const raw = items[0]?.json?.body || items[0]?.json || {};

  // ترکیب نام و نام خانوادگی در صورت وجود
  const firstName = (raw.first_name || '').trim();
  const lastName = (raw.last_name || '').trim();
  const fullName = raw.full_name || `${firstName} ${lastName}`.trim();

  const companyName = (raw.company_name || '').trim();
  const companyDomain = (raw.company_domain || '').trim();
  const email = (raw.email || '').toLowerCase().trim();
  const jobTitle = (raw.job_title || '').trim();
  const source = (raw.source || 'Direct').trim();

  // اعتبارسنجی فیلدهای ضروری
  if (!fullName || !email || !companyName) {
    throw new Error(`Missing required fields: ${[!fullName && 'full_name', !email && 'email', !companyName && 'company_name'].filter(Boolean).join(', ')}`);
  }

  // اعتبارسنجی فرمت ایمیل
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    throw new Error(`Invalid email format: ${email}`);
  }

  return [{
    json: {
      first_name: firstName,
      last_name: lastName,
      full_name: fullName,
      email: email,
      company_name: companyName,
      company_domain: companyDomain,
      job_title: jobTitle,
      source: source,
      sanitized_at: new Date().toISOString()
    }
  }];

} catch (error) {
  return [{
    json: {
      error: true,
      error_message: error.message,
      timestamp: new Date().toISOString()
    }
  }];
}

