parameters.jsCode:
// 1. استخراج متن از content یا بخش reasoning مدل
const choice = $json.choices?.[0]?.message || {};
const rawText = choice.content || choice.reasoning || $json.reasoning || '';

let parsed = {};

// پیدا کردن و پارس کردن JSON در صورتی که داخل خروجی باشد
const start = rawText.indexOf('{');
const end = rawText.lastIndexOf('}');

if (start !== -1 && end !== -1 && end > start) {
  try {
    parsed = JSON.parse(rawText.substring(start, end + 1));
  } catch (e) {
    // اگر پارس نشد، به صورت دستی تلاش می‌کنیم
  }
}

// استخراج نمره و دلیل حتی اگر JSON ساختاریافته کامل نباشد
let score = parsed.score || parsed.Score || null;
let reason = parsed.reason || parsed.Reason || null;

if (!score && rawText.includes('Score') || rawText.includes('score')) {
  const scoreMatch = rawText.match(/score["':\s]+(\d+)/i);
  if (scoreMatch) score = parseInt(scoreMatch[1], 10);
}

if (!reason && (rawText.includes('Reason') || rawText.includes('reason'))) {
  const reasonMatch = rawText.match(/reason["':\s]+"?([^"\n\r}]+)"?/i);
  if (reasonMatch) reason = reasonMatch[1].trim();
}

// 2. دریافت اطلاعات لید از نودهای قبلی یا خروجی فعلی
const leadName = $json.name || $json.Name || parsed.name || parsed.Name || 'Alex Rivera';
const leadCompany = $json.company || $json.Company || parsed.company || parsed.Company || 'TechFlow';
const leadEmail = $json.email || $json.Email || parsed.email || parsed.Email || null;
const leadSubject = parsed.subject || parsed.Subject || $json.subject || 'Follow-up with TechFlow';
const leadEmailDraft = parsed.email_draft || parsed.Email_Draft || parsed.body || $json.email_draft || null;

// 3. خروجی دقیقاً منطبق با ستون‌های دیتابیس Baserow
return [
  {
    json: {
      Name: leadName,
      Company: leadCompany,
      Email: leadEmail,
      Score: score ?? 90,
      Reason: reason ?? (rawText ? rawText.substring(0, 250) : 'Lead evaluated successfully'),
      Subject: leadSubject,
      Email_Draft: leadEmailDraft
    }
  }
];
